albums = FileAttachment("data/drake_albums.csv").csv()

viewof selected = Inputs.select(albums, {
  label: "Select an album:",
  format: d =&gt; d.title
})
















html`
&lt;div style="margin-top: 1.5em;"&gt;
  &lt;h3&gt;${selected.title}&lt;/h3&gt;
  &lt;p&gt;&lt;strong&gt;Release Date:&lt;/strong&gt; ${selected.release_date}&lt;/p&gt;
  &lt;p&gt;&lt;strong&gt;Total Spotify Streams:&lt;/strong&gt; ${Number(selected.streams).toLocaleString()}&lt;/p&gt;
  &lt;img src="${selected.cover_path}" alt="${selected.title}" style="max-width: 350px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);"&gt;

  &lt;h4 style="margin-top: 1em;"&gt;Top 3 Most Streamed Songs&lt;/h4&gt;
  &lt;ol&gt;
    &lt;li&gt;${selected.top_song_1}&lt;/li&gt;
    &lt;li&gt;${selected.top_song_2}&lt;/li&gt;
    &lt;li&gt;${selected.top_song_3}&lt;/li&gt;
  &lt;/ol&gt;
&lt;/div&gt;
`
